import XCTest
@testable import FrenchCore

/// Checks the files the app ships with, as generated by `tools/`.
final class BundledDataTests: XCTestCase {
    private static let resources = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("App/Resources")

    private func load(_ name: String) throws -> Data {
        try Data(contentsOf: Self.resources.appendingPathComponent(name))
    }

    func testContentDecodesAndIsConsistent() throws {
        let content = try Content.decode(load("content.json"))
        XCTAssertGreaterThanOrEqual(content.lessons.count, 15)
        XCTAssertEqual(Set(content.entries.map(\.id)).count, content.entries.count, "card ids must be unique")

        let ruleIDs = Set(content.lessons.flatMap(\.rules).map(\.id))
        for reading in content.readingRules { XCTAssertTrue(ruleIDs.contains(reading.rule), "reading rule points to missing rule \(reading.rule)") }

        for lesson in content.lessons {
            XCTAssertFalse(lesson.topic.isEmpty, "lesson \(lesson.id) has no topic")
            XCTAssertFalse(lesson.words.isEmpty, "lesson \(lesson.id) has no words")
            for word in lesson.words {
                guard let marked = word.m else { continue }
                XCTAssertEqual(Markup.plain(marked), word.fr, "marks change the spelling in lesson \(lesson.id)")
            }
            for case .sentence(let sentence) in lesson.sections.flatMap(\.items) {
                XCTAssertFalse(sentence.tokens.isEmpty)
                for token in sentence.tokens {
                    XCTAssertFalse(token.plain.isEmpty)
                    if let rule = token.rule { XCTAssertTrue(content.readingRules.indices.contains(rule)) }
                }
            }
        }
    }

    /// The three phrases the prototype's reader knew, with the marks typed there by hand.
    func testReaderReproducesThePrototypeSamples() throws {
        let reader = Reader(lexicon: Lexicon(forms: try load("lexicon.tsv"), lemmas: try load("lemmas.tsv")))
        let samples = [
            ("Les enfants habitent à Paris.", "Le{s}‿[en]f[an](ts) (h)abit(ent) à Pari(s).", "le z‿ɑ̃fɑ̃ abit a paʁi"),
            ("Ils ont beaucoup de temps.", "Il{s}‿[on](t) beaucou(p) de t[em](ps).", "il z‿ɔ̃ boku də tɑ̃"),
            ("Vous êtes très aimables.", "Vou{s}‿êt(es) trè{s}‿aimabl(es).", "vu z‿ɛt tʁɛ z‿ɛmabl"),
        ]
        for (phrase, marked, ipa) in samples {
            let words = reader.read(phrase)
            XCTAssertEqual(words.marked, marked)
            XCTAssertEqual(words.ipa, ipa)
        }
    }

    func testEveryLessonWordWithFormsHasAParadigm() throws {
        let lexicon = Lexicon(forms: try load("lexicon.tsv"), lemmas: try load("lemmas.tsv"))
        let grammar = Grammar(lexicon: lexicon)
        XCTAssertEqual(grammar.analyses(of: "buvons").first?.analysis.lemma, "boire")
        XCTAssertEqual(grammar.analyses(of: "petites").first?.analysis.lemma, "petit")
        let boire = try XCTUnwrap(grammar.paradigm(lemma: "boire", as: .verb))
        XCTAssertEqual(boire.sets.map(\.name), Grammar.tenseNames)
        XCTAssertEqual(boire.sets[0].forms.map(\.marked), ["je boi(s)", "tu boi(s)", "il boi(t)", "nou(s) buv[on](s)", "vou(s) buve(z)", "il(s) boiv(ent)"])
    }
}
